var n=`0908-twice-cooked-pork`;var t=`world-0908`;var o=`CN`;var a=`east-asia`;var s=4;var r=67;var d={en:`Twice-Cooked Pork`,ua:`Свинина подвійного приготування`};var g={en:`Twice-Cooked Pork is a China dish made with pork belly, doubanjiang, garlic, green onion. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Свинина подвійного приготування, страва кухні країни Китай. Основні складники: свиняча грудинка, доубаньцзян, часник, зелена цибуля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Cook the listed ingredients in simmering water for about 38 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 38 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:38,i:[[`pork-belly`,850,`g`],[`water`,950,`ml`],[`ground-ginger`,25,`g`]]},{en:`Shred or tear the cooked components, then fold together with the listed additions.`,ua:`Нашаткуйте або розберіть готові компоненти на волокна й змішайте з зазначеними додатками.`,t:[`shredding`,`mixing`],m:7,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`peanut-oil`,50,`ml`],[`doubanjiang`,50,`g`],[`garlic`,4,`clove`],[`green-onion`,60,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 9 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 9 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:9,i:[[`green-bell-pepper`,250,`g`],[`light-soy-sauce`,25,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`white-granulated-sugar`,12,`g`]]}];var u={slug:n,id:t,country:`CN`,region:a,servings:4,minutes:67,title:d,text:g,steps:l};export{o as country,u as default,t as id,r as minutes,a as region,s as servings,n as slug,l as steps,g as text,d as title};